use /lib
use /ui
from /scope/project/open-project import OpenProjectScope
from /ui/components/project-indicator import ProjectIndicator
from /scope/project-directory import ProjectDirectoryScope
from /scope/new-project import NewProjectScope

export ui-component RibbonProjectTabScope:
    concept: {RibbonProjectTabConcept}

concept RibbonProjectTabConcept:
    pitch:
        The ribbon's Project tab: the commands for the project as a whole.

    shape: {RibbonProjectTabShape}

shape RibbonProjectTabShape:
    description:
        The Project tab of the ribbon, first of the tabs and the one the window
        opens on.

    groups:
        project:
            A "Project" group holds the New Project command, then the Open
            Project command.

    commands:
        newProject:
            A "New Project" button with a folder-plus icon. Clicking it opens
            the @{NewProjectScope}, and its tooltip says it creates a new
            project and opens it.

            It is primary, and a full button.

        openProject:
            A button with a folder icon that always reads "Open Project…",
            whether or not a project is open; the @{ProjectIndicator} beside
            the ribbon's tabs shows which is. Its tooltip says to pick a
            piton.config.pi file, whose folder becomes the project.

            Clicking it opens the @{OpenProjectScope}.

            It is primary, and a slim button.
//! The ribbon's Project tab, for the project as a whole: New Project, which
//! sets up a new project and opens it, and Open Project, which picks a
//! piton.config.pi whose folder becomes the project.

use gpui_kit::assets::IconName;
use gpui_kit::component::button::Button;
use gpui_kit::*;

use super::{Command, CommandPlace, CommandSize};
use crate::new_project::NewProject;
use crate::project::open_project::OpenProject;

pub(super) const COMMANDS: &[CommandPlace] = &[
    CommandPlace {
        command: Command::NewProject,
        group: "Project",
        size: CommandSize::Full,
        primary: true,
    },
    CommandPlace {
        command: Command::OpenProject,
        group: "Project",
        size: CommandSize::Slim,
        primary: true,
    },
];

/// New Project: opens the form for a new project.
pub(super) fn new_project(
    button: impl Fn(&'static str, IconName, SharedString) -> Button,
) -> AnyElement {
    button("new-project", IconName::FolderPlus, "New Project".into())
        .tooltip("Create a new project and open it")
        .on_click(|_, window, cx| window.dispatch_action(Box::new(NewProject), cx))
        .into_any_element()
}

/// Open Project: always so, whether or not a project is open; the project
/// indicator beside the tabs shows which is. It opens a file browser for the
/// project's piton.config.pi in the main window's inset panel.
pub(super) fn open_project(
    button: impl Fn(&'static str, IconName, SharedString) -> Button,
) -> AnyElement {
    button(
        "project-directory",
        IconName::FolderOpen,
        "Open Project…".into(),
    )
    .tooltip("Pick a piton.config.pi file; its folder becomes the project")
    .on_click(|_, window, cx| window.dispatch_action(Box::new(OpenProject), cx))
    .into_any_element()
}
